/**
 * Types for modules that exist only inside Vite, generated by a plugin
 * rather than read from disk. TypeScript can't see them, so they're
 * declared here.
 */

declare module 'virtual:public-datasets' {
  import type { PublicDataset } from '@/lib/publicDatasetTypes';

  /** Everything `vite-plugins/publicDatasetCatalog.ts` found under `public/`. */
  const datasets: PublicDataset[];
  export default datasets;
}
